stage_a_raw:
{
  "decisions": [
    {
      "decision": "pair_orientation_in_objective",
      "evidence": "\"the sum of the distances between all pairs of selected facilities\" and the distance table lists both (i,j) and (j,i) with different values",
      "options": [
        "count each unordered pair once using the (i,j) entry with i<j",
        "count each ordered pair (i,j) and (j,i) separately, summing both directed distances",
        "count each unordered pair once using a symmetric distance (e.g. average or min of the two directed values)"
      ],
      "plausibility": [
        0.5,
        0.35,
        0.15
      ],
      "majority_option": "count each ordered pair (i,j) and (j,i) separately, summing both directed distances"
    },
    {
      "decision": "pair_activation_variable_domain",
      "evidence": "\"A distance between two locations is only counted if both locations are selected as facilities\"",
      "options": [
        "Binary z[i,j] with z <= y_i, z <= y_j, z >= y_i + y_j - 1",
        "Continuous z[i,j] in [0,1] with the same linking constraints",
        "No z variables; objective uses product y_i * y_j directly"
      ],
      "plausibility": [
        0.7,
        0.2,
        0.1
      ],
      "majority_option": "Binary z[i,j] with z <= y_i, z <= y_j, z >= y_i + y_j - 1"
    },
    {
      "decision": "selection_variable_domain",
      "evidence": "\"Exactly two facilities must be selected from the five available locations\"",
      "options": [
        "Binary y[i]",
        "NonNegativeIntegers y[i]",
        "NonNegativeReals y[i] in [0,1]"
      ],
      "plausibility": [
        0.85,
        0.1,
        0.05
      ],
      "majority_option": "Binary y[i]"
    },
    {
      "decision": "objective_sense",
      "evidence": "\"maximize their dispersion\" / \"maximize the total dispersion\"",
      "options": [
        "maximize total dispersion",
        "minimize total dispersion"
      ],
      "plausibility": [
        0.98,
        0.02
      ],
      "majority_option": "maximize total dispersion"
    },
    {
      "decision": "selection_constraint_direction",
      "evidence": "\"Exactly two facilities must be selected\"",
      "options": [
        "sum_i y[i] == 2",
        "sum_i y[i] <= 2",
        "sum_i y[i] >= 2"
      ],
      "plausibility": [
        0.95,
        0.03,
        0.02
      ],
      "majority_option": "sum_i y[i] == 2"
    },
    {
      "decision": "logical_consistency_lower_bound",
      "evidence": "\"if a pair of locations is selected, the distance between them must be fully accounted for\"",
      "options": [
        "include z[i,j] >= y_i + y_j - 1 (forces z=1 when both selected)",
        "omit the lower bound and rely only on z <= y_i, z <= y_j (z may stay 0)"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "include z[i,j] >= y_i + y_j - 1 (forces z=1 when both selected)"
    }
  ]
}
